contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dep, uint256 extra) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(dep > 0);
        require(extra > 0);
        require(dep <= type(uint256).max - extra);

        uint256 amountOver = dep + extra;
        require(address(this).balance >= amountOver);

        uint256 cBeforeDeposit = address(c).balance;

        c.deposit{value: dep}(); if (__ESBMC_reverted()) return;
        uint256 cAfterDeposit = address(c).balance;

        bool revertedOver;
        c.withdraw(amountOver); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedOver = true;
        } else {
            revertedOver = false;
        }
        uint256 cAfterOver = address(c).balance;

        bool revertedExact;
        c.withdraw(dep); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedExact = true;
        } else {
            revertedExact = false;
        }
        uint256 cAfterExact = address(c).balance;

        assert(
            revertedOver &&
            cAfterOver == cAfterDeposit &&
            !revertedExact &&
            cAfterExact == cBeforeDeposit
        );
    }

    receive() external payable {}
}

