pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dep, uint256 extra) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dep > 0);
        vm.assume(extra > 0);
        vm.assume(dep <= type(uint256).max - extra);
        uint256 amountOver = dep + extra;
        vm.assume(address(this).balance >= amountOver);
        uint256 cBeforeDeposit = address(c).balance;
        try c.deposit{value: dep}() {} catch { return; }
        uint256 cAfterDeposit = address(c).balance;
        bool revertedOver;
        try c.withdraw(amountOver) {
            revertedOver = false;
        } catch {
            revertedOver = true;
        }
        uint256 cAfterOver = address(c).balance;
        bool revertedExact;
        try c.withdraw(dep) {
            revertedExact = false;
        } catch {
            revertedExact = true;
        }
        uint256 cAfterExact = address(c).balance;
        assertTrue(revertedOver &&
            cAfterOver == cAfterDeposit &&
            !revertedExact &&
            cAfterExact == cBeforeDeposit);
    }

    function testFuzz_run(uint256 dep, uint256 extra) public {
        _run(dep, extra);
    }

    receive() external payable {}
}
